 }
 .showroom-badge.is-available { background: #10b981; color: #ffffff; }
 .showroom-badge.is-booked { background: #f59e0b; color: #ffffff; }
 .showroom-badge.is-sold { background: #ef233c; color: #ffffff; }
 .showroom-badge.is-inactive { background: #64748b; color: #ffffff; }
 .showroom-badge.is-highlight { background: #8b5cf6; color: #ffffff; }
 .showroom-badge.is-condition { background: rgba(15, 23, 42, 0.85); color: #ffffff; }

 .showroom-body {
 padding: 18px;
 display: flex;
 flex-direction: column;
 flex: 1;
 }
 .showroom-top {
 display: flex;
 justify-content: space-between;
 align-items: flex-start;
 gap: 10px;
 margin-bottom: 8px;
 }
 .showroom-title {
 margin: 0;
 font-size: 16px;
 font-weight: 800;
 color: #0f172a;
 }
 .showroom-sub {
 margin: 3px 0 0;
 font-size: 11px;
 color: #64748b;
 }
 .showroom-slug-pill {
 padding: 3px 8px;
 border-radius: 6px;
 background: #f1f5f9;
 color: #475569;
 font-size: 10px;
 font-weight: 700;
 white-space: nowrap;
 }
 .showroom-price-row {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 10px;
 margin: 8px 0 12px;
 }
 .showroom-price {
 font-size: 18px;
 font-weight: 800;
 color: #ef233c;
 }
 .showroom-stock-pill {
 padding: 3px 8px;
 border-radius: 6px;
 font-size: 10px;
 font-weight: 700;
 }
 .showroom-stock-pill.is-stock { background: #ecfdf5; color: #047857; }
 .showroom-stock-pill.is-nostock { background: #fee2e2; color: #b91c1c; }

 .showroom-meta-chips {
 display: flex;
 flex-wrap: wrap;
 gap: 6px;
 margin-bottom: 12px;
 }
 .showroom-meta-chips span {
 padding: 4px 8px;
 border-radius: 6px;
 background: #f8fafc;
 border: 1px solid #e2e8f0;
 font-size: 11px;
 color: #475569;
 }
 .showroom-description {
 font-size: 12px;
 color: #64748b;
 line-height: 1.45;
 margin: 0 0 16px;
 }
 .showroom-actions-row {
 display: flex;
 gap: 8px;
 margin-top: auto;
 }
 .btn-showroom-detail, .btn-showroom-edit, .btn-showroom-preview {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 5px;
 padding: 8px 12px;
 border-radius: 8px;
 font-size: 12px;
 font-weight: 700;
 text-decoration: none;
 text-align: center;
 cursor: pointer;
 border: 0;
 }
 .btn-showroom-detail {
 flex: 2;
 background: #ef233c;
 color: #ffffff;
 box-shadow: 0 3px 10px rgba(239, 35, 60, 0.2);
 }
 .btn-showroom-detail:hover { color: #ffffff; background: #d90429; }
 .btn-showroom-edit {
 flex: 1;
 border: 1px solid #cbd5e1;
 color: #334155;
 background: #ffffff;
 }
 .btn-showroom-edit:hover { background: #f8fafc; color: #0f172a; }
 .btn-showroom-preview {
 border: 1px solid #e2e8f0;
 color: #64748b;
 background: #f8fafc;
 }

 /* TAB 3: FOTO & WARNA */
 .gallery-management-container {
 padding: 24px;
 display: flex;
 flex-direction: column;
 gap: 28px;
 }
 .car-gallery-card {
 border: 1px solid #e2e8f0;
 border-radius: 12px;
 background: #ffffff;
 padding: 20px;
 box-shadow: 0 2px 8px rgba(15, 23, 42, 0.03);
 }
 .car-gallery-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 16px;
 padding-bottom: 16px;
 border-bottom: 1px solid #f1f5f9;
 margin-bottom: 18px;
 flex-wrap: wrap;
 }
 .gallery-car-meta {
 display: flex;
 flex-direction: column;
 gap: 4px;
 }
 .gallery-car-code {
 font-family: ui-monospace, SFMono-Regular, monospace;
 font-size: 11px;
 font-weight: 700;
 color: #ef233c;
 }
 .gallery-car-name {
 margin: 0;
 font-size: 17px;
 font-weight: 800;
 color: #0f172a;
 }
 .gallery-car-name small {
 color: #64748b;
 font-weight: 600;
 }
 .gallery-color-distinction {
 display: flex;
 gap: 8px;
 margin-top: 4px;
 flex-wrap: wrap;
 }
 .badge-physical-color {
 padding: 4px 8px;
 border-radius: 6px;
 background: #e0f2fe;
 color: #0369a1;
 font-size: 11px;
 }
 .badge-showroom-status {
 padding: 4px 8px;
 border-radius: 6px;
 background: #f1f5f9;
 color: #475569;
 font-size: 11px;
 }
 .gallery-car-actions {
 display: flex;
 gap: 8px;
 }
 .btn-sm-ghost {
 padding: 6px 12px;
 border-radius: 6px;
 border: 1px solid #cbd5e1;
 color: #475569;
 font-size: 11px;
 font-weight: 600;
 text-decoration: none;
 background: #ffffff;
 cursor: pointer;
 }
 .btn-sm-ghost:hover { background: #f8fafc; color: #0f172a; }

 /* 4 Sudut Visual Grid */
 .visual-angles-grid {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: 14px;
 margin-bottom: 20px;
 }
 .angle-card {
 border: 1px solid #e2e8f0;
 border-radius: 10px;
 overflow: hidden;
 background: #fafbfc;
 }
 .angle-view-box {
 height: 120px;
 background: #0f172a;
 display: flex;
 align-items: center;
 justify-content: center;
 overflow: hidden;
 }
 .angle-view-box img {
 width: 100%;
 height: 100%;
 object-fit: cover;
 }
 .angle-placeholder {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 gap: 6px;
 padding: 12px;
 text-align: center;
 color: #94a3b8;
 font-size: 10px;
 }
 .angle-caption {
 display: flex;
 align-items: center;
 justify-content: space-between;
 padding: 8px 10px;
 font-size: 11px;
 font-weight: 700;
 color: #334155;
 background: #ffffff;
 }
 .badge-dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 }
 .badge-dot.is-active { background: #10b981; }
 .badge-dot.is-inactive { background: #cbd5e1; }

 /* Colors Section */
 .car-colors-section {
 padding: 14px 16px;
 border-radius: 8px;
 background: #f8fafc;
 border: 1px solid #e2e8f0;
 margin-bottom: 20px;
 }
 .section-micro-title {
 margin: 0 0 10px;
 font-size: 12px;
 font-weight: 800;
 color: #0f172a;
 text-transform: uppercase;
 letter-spacing: 0.03em;
 }
 .color-swatches-list {
 display: flex;
 flex-wrap: wrap;
 gap: 10px;
 }
 .color-chip {
 display: flex;
 align-items: center;
 gap: 8px;
 padding: 6px 10px;
 border-radius: 8px;
 background: #ffffff;
 border: 1px solid #cbd5e1;
 }
 .color-chip.is-default {
 border-color: #ef233c;
 background: #fff5f5;
 }
 .color-circle {
 width: 18px;
 height: 18px;
 border-radius: 50%;
 border: 1px solid rgba(0, 0, 0, 0.15);
 }
 .color-chip-info {
 display: flex;
 flex-direction: column;
 font-size: 11px;
 }
 .color-chip-info strong { color: #0f172a; }
 .color-chip-info small { color: #64748b; font-family: monospace; font-size: 9px; }
 .chip-tag-default {
 font-size: 9px;
 font-weight: 800;
 color: #ef233c;
 text-transform: uppercase;
 }
 .color-empty-notice {
 font-size: 12px;
 color: #64748b;
 }

 /* Uploaded Photos Grid */
 .car-uploaded-photos-section {
 padding: 14px 16px;
 border-radius: 8px;
 background: #ffffff;
 border: 1px solid #e2e8f0;
 }
 .uploaded-photos-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 margin-bottom: 12px;
 }
 .btn-upload-file {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 padding: 6px 12px;
 border-radius: 6px;
 background: #0f172a;
 color: #ffffff;
 font-size: 11px;
 font-weight: 700;
 cursor: pointer;
 }
 .uploaded-thumbnails-grid {
 display: grid;
 grid-template-columns: repeat(6, 1fr);
 gap: 10px;
 }
 .uploaded-photo-card {
 position: relative;
 height: 90px;
 border-radius: 8px;
 overflow: hidden;
 background: #0f172a;
 border: 2px solid transparent;
 }
 .uploaded-photo-card.is-primary {
 border-color: #ef233c;
 }
 .uploaded-photo-card img {
 width: 100%;
 height: 100%;
 object-fit: cover;
 }
 .uploaded-photo-overlay {
 position: absolute;
 inset: 0;
 background: rgba(15, 23, 42, 0.6);
 display: flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
 opacity: 0;
 transition: opacity 0.15s ease;
 }
 .uploaded-photo-card:hover .uploaded-photo-overlay {
 opacity: 1;
 }
 .badge-primary-photo {
 padding: 3px 6px;
 border-radius: 4px;
 background: #ef233c;
 color: #ffffff;
 font-size: 10px;
 font-weight: 800;
 }
 .btn-action-photo {
 padding: 4px 8px;
 border-radius: 4px;
 font-size: 10px;
 font-weight: 700;
 border: 0;
 cursor: pointer;
 }
 .btn-action-photo.set-primary { background: #ffffff; color: #0f172a; }
 .btn-action-photo.delete { background: #fee2e2; color: #dc2626; }
 .no-uploaded-photos {
 grid-column: 1 / -1;
 font-size: 12px;
 color: #94a3b8;
 padding: 10px 0;
 }

 .catalog-empty-full {
 padding: 48px;
 text-align: center;
 color: #64748b;
 font-size: 13px;
 }

 /* ========================================================
 REUSABLE PREMIUM ACTION MODAL STYLES
 ======================================================== */
 .vehicle-modal-backdrop {
 position: fixed;
 inset: 0;
 background: rgba(15, 23, 42, 0.6);
 backdrop-filter: blur(4px);
 z-index: 10000;
 display: flex;
 align-items: center;
 justify-content: center;
 padding: 20px;
 opacity: 1;
 transition: opacity 200ms ease-out;
 }
 .vehicle-modal-backdrop[hidden] {
 display: none;
 opacity: 0;
 }
 .vehicle-modal-dialog {
 position: relative;
 width: 100%;
 max-width: 900px;
 max-height: 88dvh;
 border-radius: 16px;
 background: #ffffff;
 border: 1px solid #e2e8f0;
 box-shadow: 0 24px 48px -12px rgba(15, 23, 42, 0.25);
 display: flex;
 flex-direction: column;
 overflow: hidden;
 transform: translateY(0);
 transition: transform 200ms ease-out;
 }
 .vehicle-modal-dialog.is-compact {
 max-width: 520px;
 }
 .vehicle-modal-dialog.is-medium {
 max-width: 680px;
 }

 @media (prefers-reduced-motion: no-preference) {
 .vehicle-modal-backdrop:not([hidden]) .vehicle-modal-dialog {
 animation: modalSlideUp 200ms ease-out;
 }
 }
 @keyframes modalSlideUp {
 from { transform: translateY(8px); opacity: 0.85; }
 to { transform: translateY(0); opacity: 1; }
 }

 @keyframes modalSpin {
 to { transform: rotate(360deg); }
 }

 .vehicle-modal-header {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 16px;
 padding: 20px 24px 16px;
 border-bottom: 1px solid #edf2f7;
 background: #ffffff;
 }
 .modal-header-titles {
 display: flex;
 flex-direction: column;
 gap: 3px;
 }
 .modal-kicker {
 font-size: 10px;
 font-weight: 800;
 text-transform: uppercase;
 color: #ef233c;
 letter-spacing: 0.08em;
 }
 .modal-title {
 margin: 0;
 font-size: 19px;
 font-weight: 800;
 color: #0f172a;
 letter-spacing: -0.01em;
 }
 .modal-header-meta {
 display: flex;
 align-items: center;
 gap: 8px;
 margin-top: 4px;
 font-size: 12px;
 color: #64748b;
 }
 .vehicle-modal-close {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 width: 34px;
 height: 34px;
 border-radius: 8px;
 border: 1px solid #e2e8f0;
 background: #ffffff;
 color: #64748b;
 cursor: pointer;
 transition: background 0.12s ease, color 0.12s ease;
 }
 .vehicle-modal-close:hover {
 background: #f1f5f9;
 color: #0f172a;
 }

 /* Modal Nav Tabs */
 .modal-nav-tabs {
 display: flex;
 padding: 0 24px;
 gap: 6px;
 border-bottom: 1px solid #e2e8f0;
 background: #fafbfc;
 }
 .modal-tab-btn {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 padding: 10px 14px;
 border: 0;
 border-bottom: 2px solid transparent;
 background: transparent;
 font-size: 12px;
 font-weight: 700;
 color: #64748b;
 cursor: pointer;
 margin-bottom: -1px;
 transition: color 0.12s ease, border-color 0.12s ease;
 }
 .modal-tab-btn:hover { color: #0f172a; }
 .modal-tab-btn.is-active {
 color: #ef233c;
 border-bottom-color: #ef233c;
 }

 /* Modal Body */
 .vehicle-modal-body {
 padding: 20px 24px;
 overflow-y: auto;
 flex: 1;
 font-size: 13px;
 color: #334155;
 }

 /* Modal Footer */
 .vehicle-modal-footer {
 display: flex;
 align-items: center;
 justify-content: flex-end;
 gap: 10px;
 padding: 14px 24px;
 border-top: 1px solid #edf2f7;
 background: #fafbfc;
 }
 .btn-modal-primary {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
 height: 38px;
 padding: 0 18px;
 border-radius: 8px;
 background: #ef233c;
 color: #ffffff;
 font-size: 12px;
 font-weight: 700;
 border: 0;
 cursor: pointer;
 box-shadow: 0 3px 10px rgba(239, 35, 60, 0.2);
 }
 .btn-modal-primary:hover { background: #d90429; color: #ffffff; }
 .btn-modal-danger {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
 height: 38px;
 padding: 0 18px;
 border-radius: 8px;
 background: #dc2626;
 color: #ffffff;
 font-size: 12px;
 font-weight: 700;
 border: 0;
 cursor: pointer;
 }
 .btn-modal-danger:hover { background: #b91c1c; }
 .btn-modal-secondary {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 6px;
 height: 38px;
 padding: 0 16px;
 border-radius: 8px;
 background: #ffffff;
 color: #475569;
 font-size: 12px;
 font-weight: 600;
 border: 1px solid #cbd5e1;
 cursor: pointer;
 }
 .btn-modal-secondary:hover { background: #f8fafc; color: #0f172a; }

 /* Modal Panes Visibility & Content Segregation */
 .modal-pane {
 display: none;
 animation: fadeInModalPane 150ms cubic-bezier(0.16, 1, 0.3, 1);
 }
 .modal-pane.is-active,
 .modal-pane:not(.hidden) {
 display: block;
 }
 .modal-pane.hidden {
 display: none !important;
 }
 @keyframes fadeInModalPane {
 from { opacity: 0; transform: translateY(4px); }
 to { opacity: 1; transform: translateY(0); }
 }

 .modal-strip-summary {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 12px;
 padding: 10px 14px;
 border-radius: 10px;
 background: #f1f5f9;
 border: 1px solid #cbd5e1;
 font-size: 12px;
 color: #334155;
 margin-bottom: 14px;
 }
 .modal-strip-summary strong {
 color: #0f172a;
 }
 .color-chip.is-interactive {
 cursor: pointer;
 transition: transform 0.12s ease, border-color 0.12s ease, box-shadow 0.12s ease;
 }
 .color-chip.is-interactive:hover {
 transform: translateY(-1px);
 border-color: #94a3b8;
 }
 .color-chip.is-interactive.is-selected {
 border-color: #ef233c;
 background: #fff5f5;
 box-shadow: 0 0 0 2px rgba(239, 35, 60, 0.2);
 }
 .gallery-active-preview {
 width: 100%;
 height: 220px;
 border-radius: 12px;
 overflow: hidden;
 background: #0f172a;
 display: flex;
 align-items: center;
 justify-content: center;
 margin-bottom: 16px;
 border: 1px solid #e2e8f0;
 }
 .gallery-active-preview img {
 width: 100%;
 height: 100%;
 object-fit: cover;
 }

 /* Modal Content Layouts */
 .modal-grid-2col {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: 16px;
 }
 .modal-detail-hero {
 display: flex;
 gap: 18px;
 align-items: center;
 padding: 14px 18px;
 border-radius: 12px;
 background: #f8fafc;
 border: 1px solid #e2e8f0;
 margin-bottom: 18px;
 }
 .modal-detail-thumb {
 width: 140px;
 height: 90px;
 border-radius: 8px;
 overflow: hidden;
 background: #0f172a;
 flex-shrink: 0;
 }
 .modal-detail-thumb img {
 width: 100%;
 height: 100%;
 object-fit: cover;
 }
 .modal-hero-info {
 display: flex;
 flex-direction: column;
 gap: 4px;
 }
 .modal-hero-price {
 font-size: 20px;
 font-weight: 800;
 color: #ef233c;
 }
 .modal-spec-dl {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: 10px 16px;
 margin: 0;
 }
 .modal-spec-row {
 display: flex;
 flex-direction: column;
 padding: 8px 12px;
 border-radius: 8px;
 background: #f8fafc;
 border: 1px solid #edf2f7;
 }
 .modal-spec-row.is-full {
 grid-column: 1 / -1;
 }
 .modal-spec-row dt {
 font-size: 11px;
 font-weight: 700;
 color: #64748b;
 text-transform: uppercase;
 }
 .modal-spec-row dd {
 margin: 3px 0 0;
 font-size: 13px;
 font-weight: 600;
 color: #0f172a;
 }

 /* Modal Form Controls */
 .modal-form-group {
 display: flex;
 flex-direction: column;
 gap: 5px;
 margin-bottom: 14px;
 }
 .modal-form-label {
 font-size: 12px;
 font-weight: 700;
 color: #334155;
 }
 .modal-form-label .required-mark { color: #ef233c; }
 .modal-form-input, .modal-form-select, .modal-form-textarea {
 width: 100%;
 height: 38px;
 padding: 0 12px;
 border-radius: 8px;
 border: 1px solid #cbd5e1;
 font-size: 13px;
 color: #1e293b;
 background: #ffffff;
 outline: none;
 transition: border-color 0.15s ease, box-shadow 0.15s ease;
 }
 .modal-form-textarea {
 height: 70px;
 padding: 8px 12px;
 resize: vertical;
 }
 .modal-form-input:focus, .modal-form-select:focus, .modal-form-textarea:focus {
 border-color: #ef233c;
 box-shadow: 0 0 0 3px rgba(239, 35, 60, 0.1);
 }
 .modal-field-error {
 font-size: 11px;
 color: #dc2626;
 margin-top: 3px;
 }

 /* Modal Info Callouts */
 .modal-info-callout {
 display: flex;
 gap: 12px;
 padding: 12px 16px;
 border-radius: 10px;
 background: #eff6ff;
 border: 1px solid #bfdbfe;
 color: #1e40af;
 font-size: 12px;
 margin-bottom: 16px;
 align-items: center;
 }
 .modal-warning-callout {
 display: flex;
 gap: 12px;
 padding: 12px 16px;
 border-radius: 10px;
 background: #fef2f2;
 border: 1px solid #fecaca;
 color: #991b1b;
 font-size: 12px;
 margin-bottom: 16px;
 align-items: center;
 }

 /* Timeline / History Table */
 .modal-history-table {
 width: 100%;
 border-collapse: collapse;
 font-size: 12px;
 }
 .modal-history-table th {
 padding: 10px 12px;
 background: #f8fafc;
 color: #475569;
 font-size: 11px;
 font-weight: 700;
 text-transform: uppercase;
 border-bottom: 1px solid #e2e8f0;
 text-align: left;
 }
 .modal-history-table td {
 padding: 10px 12px;
 border-bottom: 1px solid #f1f5f9;
 color: #334155;
 vertical-align: middle;
 }

 /* Pre-Order & Add Unit Modal Components */
 .vehicle-modal-dialog.is-wide {
 max-width: 860px;
 }
 body.modal-open {
 overflow: hidden !important;
 }
 .preorder-modal-summary-bar {
 display: grid;
 grid-template-columns: repeat(3, 1fr);
 gap: 12px;
 margin-bottom: 16px;
 }
 .summary-stat-box {
 padding: 12px 14px;
 border-radius: 10px;
 background: #f8fafc;
 border: 1px solid #e2e8f0;
 display: flex;
 flex-direction: column;
 gap: 4px;
 }
 .stat-label {
 font-size: 10px;
 font-weight: 800;
 text-transform: uppercase;
 color: #64748b;
 letter-spacing: 0.04em;
 }
 .stat-number {
 font-size: 20px;
 font-weight: 800;
 color: #0f172a;
 }
 .stat-badge {
 font-size: 12px;
 font-weight: 700;
 color: #0284c7;
 }
 .stat-note {
 font-size: 13px;
 font-weight: 800;
 color: #ef233c;
 }
 .preorder-empty-box {
 padding: 36px 20px;
 text-align: center;
 color: #64748b;
 background: #f8fafc;
 border: 1px dashed #cbd5e1;
 border-radius: 12px;
 display: flex;
 flex-direction: column;
 align-items: center;
 gap: 8px;
 }
 .preorder-empty-box h4 {
 margin: 8px 0 0;
 color: #0f172a;
 font-size: 15px;
 font-weight: 700;
 }
 .preorder-empty-box p {
 margin: 0;
 font-size: 12px;
 max-width: 440px;
 }
 .po-code-tag {
 font-family: ui-monospace, SFMono-Regular, monospace;
 font-size: 11px;
 color: #0284c7;
 background: #e0f2fe;
 padding: 2px 6px;
 border-radius: 4px;
 }
 .po-member-cell {
 display: flex;
 flex-direction: column;
 gap: 2px;
 }
 .po-member-code {
 font-family: ui-monospace, SFMono-Regular, monospace;
 font-size: 10px;
 color: #64748b;
 }
 .po-color-pill {
 display: inline-flex;
 align-items: center;
 gap: 4px;
 padding: 2px 8px;
 border-radius: 999px;
 background: #f1f5f9;
 font-size: 11px;
 font-weight: 600;
 color: #334155;
 }
 .btn-po-review {
 display: inline-flex;
 align-items: center;
 gap: 4px;
 padding: 5px 10px;
 border-radius: 6px;
 background: #eff6ff;
 color: #1d4ed8;
 border: 1px solid #bfdbfe;
 font-size: 11px;
 font-weight: 700;
 cursor: pointer;
 transition: all 0.12s ease;
 }
 .btn-po-review:hover {
 background: #dbeafe;
 color: #1e40af;
 transform: translateY(-1px);
 }
 .btn-preorder-back {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 padding: 6px 12px;
 border-radius: 6px;
 background: #f1f5f9;
 color: #334155;
 border: 1px solid #cbd5e1;
 font-size: 12px;
 font-weight: 700;
 cursor: pointer;
 transition: all 0.12s ease;
 }
 .btn-preorder-back:hover {
 background: #e2e8f0;
 color: #0f172a;
 }
 .preorder-review-nav {
 display: flex;
 align-items: center;
 justify-content: space-between;
 margin-bottom: 16px;
 padding-bottom: 12px;
 border-bottom: 1px solid #e2e8f0;
 }
 .preorder-card-box {
 padding: 16px;
 border-radius: 12px;
 background: #f8fafc;
 border: 1px solid #e2e8f0;
 }
 .card-box-title {
 margin: 0 0 12px;
 font-size: 13px;
 font-weight: 700;
 color: #0f172a;
 display: flex;
 align-items: center;
 gap: 6px;
 }
 .preorder-stock-status-box {
 padding: 14px 16px;
 border-radius: 10px;
 border: 1px solid #e2e8f0;
 }
 .preorder-stock-status-box.is-available {
 background: #ecfdf5;
 border-color: #a7f3d0;
 color: #065f46;
 }
 .preorder-stock-status-box.is-waiting {
 background: #fffbeb;
 border-color: #fde68a;
 color: #92400e;
 }
 .status-box-header {
 display: flex;
 align-items: center;
 gap: 8px;
 font-size: 13px;
 font-weight: 700;
 }
 .btn-action-inline {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 padding: 6px 12px;
 border-radius: 6px;
 background: #059669;
 color: #ffffff;
 border: 0;
 font-size: 11px;
 font-weight: 700;
 cursor: pointer;
 transition: background 0.12s ease;
 }
 .btn-action-inline:hover {
 background: #047857;
 }
 .modal-form-input.has-error,
 .modal-form-select.has-error,
 .modal-form-textarea.has-error {
 border-color: #ef233c !important;
 background: #fff5f5 !important;
 }
 .form-field-error {
 color: #dc2626;
 font-size: 11px;
 font-weight: 600;
 margin-top: 3px;
 display: block;
 }

 @media (prefers-reduced-motion: reduce) {
 .vehicle-modal-backdrop,
 .vehicle-modal-dialog,
 .btn-row-action,
 .btn-primary-action,
 .modal-pane {
 animation: none !important;
 transition: none !important;
 }
 }

 /* Responsive */
 @media (max-width: 1280px) {
 .vehicle-kpi-grid { grid-template-columns: repeat(3, 1fr); }
 .showroom-card-grid { grid-template-columns: repeat(2, 1fr); }
 .visual-angles-grid { grid-template-columns: repeat(2, 1fr); }
 }
 @media (max-width: 900px) {
 .vehicle-kpi-grid { grid-template-columns: repeat(2, 1fr); }
 .vehicle-filter-toolbar { grid-template-columns: 1fr; }
 .showroom-card-grid { grid-template-columns: 1fr; }
 .visual-angles-grid { grid-template-columns: 1fr; }
 .uploaded-thumbnails-grid { grid-template-columns: repeat(3, 1fr); }
 .modal-grid-2col { grid-template-columns: 1fr; }
 }
 @media (max-width: 640px) {
 .vehicle-header { flex-direction: column; align-items: flex-start; }
 .vehicle-kpi-grid { grid-template-columns: 1fr; }
 .vehicle-tabs-nav { flex-wrap: wrap; }
 .vehicle-modal-dialog { max-height: 94dvh; border-radius: 12px; }
 }
